13:     /// <summary>
14:     /// 线程的交互信号
15:     /// </summary>
16:     public class Signal
17:     {
18:         /// <summary>
19:         /// 信号名称
20:         /// </summary>
21:         public string name { get; set; }
22: 
23:         /// <summary>
24:         /// 信号状态
25:         /// </summary>
26:         public SignalStateEnum State { get; set; } = SignalStateEnum.ReSet;
27: 
28:         /// <summary>
29:         /// 自动重置还是手动
30:         /// </summary>
31:         private EventResetMode resetMode { get; set; }
32: 
33:         /// <summary>
34:         /// 自动信号
35:         /// </summary>
36:         private EventWaitHandle signalEvent;
37: 
38:         /// <summary>
39:         /// 循环周期
40:         /// </summary>
41:         private int recycleTime = 5;
42: 
43:         /// <summary>
44:         /// 构造函数
45:         /// </summary>
46:         /// <param name="name">信号名称</param>
47:         public Signal(string name) : this(name, 100, EventResetMode.AutoReset, false)
48:         {
49:         }
50: 
51:         /// <summary>
52:         /// 构造函数
53:         /// </summary>
54:         /// <param name="name">信号名称</param>
55:         /// <param name="mode">
56:         ///    信号模式：
57:         ///      EventResetMode.AutoReset 创建AutoResetEvent
58:         ///      EventResetMode.ManualReset 创建ManualResetEvent
59:         /// </param>
60:         public Signal(string name, EventResetMode mode) : this(name, 100, mode, false)
61:         {
62:         }
63: 
64:         /// <summary>
65:         /// 构造函数
66:         /// </summary>
67:         /// <param name="name">信号名称</param>
68:         /// <param name="recycleTime">循环周期</param>
69:         /// <param name="mode">
70:         ///    信号模式：
71:         ///      EventResetMode.AutoReset 创建AutoResetEvent
72:         ///      EventResetMode.ManualReset 创建ManualResetEvent
73:         /// </param>
74:         /// <param name="initialState">信号名称</param>
75:         public Signal(string name, int recycleTime, EventResetMode mode, bool initialState)
76:         {
77:             this.name = name;
78:             this.signalEvent = new EventWaitHandle(initialState, mode);
79:             this.recycleTime = recycleTime;
80:             this.resetMode = mode;
81:         }
82: 
83:         /// <summary>
84:         /// 发送信号
85:         /// </summary>
86:         /// <exception cref="InvalidOperationException">信号发送失败异常</exception>
87:         public void Set()
88:         {
89:             if (!this.signalEvent.Set())
90:             {
91:                 throw new InvalidOperationException($"{this.name} 信号发送失败");
92:             }
93: 
94:             this.State = SignalStateEnum.Set;
95:         }
96: 
97:         /// <summary>
98:         /// 信号重置
99:         /// </summary>
100:         /// <exception cref="InvalidOperationException">信号发送失败异常</exception>
101:         public void ReSet()
102:         {
103:             if (!this.signalEvent.Reset())
104:             {
105:                 throw new InvalidOperationException($"{this.name} 信号发送失败");
106:             }
107: 
108:             this.State = SignalStateEnum.ReSet;
109:         }
110: 
111:         /// <summary>
112:         /// 等待信号  如果设备处于暂停状态，循环阻塞接收信号，如果设备停止 则返回false
113:         /// 所以在启动的时候 需要先设置设备状态，再启动线程
114:         /// </summary>
115:         /// <returns>等待成功</returns>
116:         public bool Wait()
117:         {
118:             bool res = WaitStart();
119:              
120:             // 等于false 则点了停止按钮，否则是从暂停恢复到工作状态
121:             if (res == false) 
122:             { 
123:                 return false; 
124:             }
125: 
126:             // 先判断设备状态，如果设备状态为停止，则不用判断信号量了
127:             do
128:             {
129:                 if (MachineStateModel.GetInstance().MachineState == MachineStateEnum.Stop)
130:                 {
131:                     return false;
132:                 }
133: 
134:                 Thread.Sleep(5);
135:             }
136:             while (!this.signalEvent.WaitOne(this.recycleTime));
137: 
138:             // 唐鹏添加
139:             if (this.resetMode == EventResetMode.AutoReset)
140:             {
141:                 this.State = SignalStateEnum.ReSet;
142:             }
143: 
144:             return true;
145:         }
146: 
147:         /// <summary>
148:         /// 等待信号  如果设备处于暂停状态，循环阻塞接收信号，如果设备停止 则返回false
149:         /// 所以在启动的时候 需要先设置设备状态，再启动线程
150:         /// </summary>
151:         /// <param name="outTime">超时时间</param>
152:         /// <returns>结果</returns>
153:         public bool Wait(int outTime)
154:         {
155:             bool res = WaitStart();
156: 
157:             // 等于false 则点了停止按钮，否则是从暂停恢复到工作状态
158:             if (res == false)
159:             {
160:                 return false;
161:             }
162: 
163:             if (MachineStateModel.GetInstance().MachineState == MachineStateEnum.Stop)
164:             {
165:                 return false;
166:             }
167: 
168:             return this.signalEvent.WaitOne(this.recycleTime);
169:         }
170: 
171:         /// <summary>
172:         /// 等待单步信号  
173:         /// </summary>
174:         /// <returns>等待成功</returns>
175:         public bool WaitSingleStep()
176:         {
177:             do
178:             {
179:                 // 如果不是单步模式，直接退出
180:                 if (MachineStateModel.GetInstance().IsSingleStepWork == false) 
181:                 {
182:                     return false;
183:                 }
184: 
185:                 Thread.Sleep(5);
186:             }
187:             while (!this.signalEvent.WaitOne(this.recycleTime));
188: 
189:             // 唐鹏添加
190:             if (this.resetMode == EventResetMode.AutoReset)
191:             {
192:                 this.State = SignalStateEnum.ReSet;
193:             }
194: 
195:             return true;
196:         }
197: 
198:         /// <summary>
199:         ///  等待开始  用于暂停时候的阻塞
200:         /// </summary>
201:         /// <returns>结果</returns>
202:         public static bool WaitStart()
203:         {
204:             // 维护模式 和调试模式 直接返回true
205:             //if (MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.MaintenceWork 
206:             //    || MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.Debug)
207:             //{
208:             //   // return true;               
209:             //}
210: 
211:             if (MachineStateModel.GetInstance().MachineState == MachineStateEnum.Stop)
212:             {
213:                 return false;
214:             }
215: 
216:             // 暂停状态 阻塞 
217:             while (MachineStateModel.GetInstance().MachineState == MachineStateEnum.Pause)
218:             {
219:                 if (MachineStateModel.GetInstance().MachineState == MachineStateEnum.Stop)
220:                 {
221:                     return false;
222:                 }
223: 
224:                 Thread.Sleep(20);
225:             }
226: 
227:             return true;
228:         }
229:     }
230: }

